#include <bits/stdc++.h>
using namespace std;
bool isPrime(int x){
    if(x<2) return false;
    for(int i=2;(long long)i*i<=x;i++) if(x%i==0) return false;
    return true;
}
int main(){
    int t; cin>>t;
    for(int tc=1;tc<=t;tc++){
        string s; cin>>s;
        int freq[256]={0};
        for(unsigned char c : s) freq[c]++;
        string res;
        for(int c=0;c<256;c++) if(freq[c]>0 && isPrime(freq[c])) res += (char)c;
        cout << "Case " << tc << ": " << (res.empty()? "empty" : res) << "\n";
    }
}

